@include('layouts._palette')
<style>
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Maiandra GD", Calibri, "Segoe UI", Arial, sans-serif}h1,h2,h3,.brand strong{font-family:Corbel, Calibri, "Segoe UI", Arial, sans-serif;font-weight:700}a{color:inherit}.shell{min-height:100vh}.sidebar{position:fixed;inset:0 auto 0 0;width:264px;padding:24px 16px;background:var(--dark);color:#fff;display:flex;flex-direction:column;z-index:20}.brand{display:flex;align-items:center;gap:12px;margin:0 8px 32px;color:inherit;text-decoration:none}.brand-icon{width:42px;height:42px;border-radius:9px;background:var(--green);border:1px solid #ffffff2c;display:grid;place-items:center;font-size:20px}.brand strong{display:block;font-size:18px}.brand small{display:block;margin-top:3px;color:#b8d5cc;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.side-nav{min-height:0;flex:1;display:grid;align-content:start;gap:5px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#ffffff55 transparent;padding-right:4px}.side-nav::-webkit-scrollbar{width:6px}.side-nav::-webkit-scrollbar-thumb{border-radius:99px;background:#ffffff55}.side-nav::-webkit-scrollbar-track{background:transparent}.side-nav a{position:relative;display:flex;align-items:center;gap:11px;min-height:44px;padding:11px 13px;border-radius:8px;text-decoration:none;color:#d6e8e2;font-size:14px}.side-nav a:hover{background:#ffffff12;color:#fff}.side-nav a.active{background:#ffffff18;color:#fff;font-weight:700}.side-nav a.active:before{content:"";position:absolute;left:0;top:9px;bottom:9px;width:3px;border-radius:3px;background:var(--gold)}.nav-icon{width:21px;text-align:center;color:#c7ded7}.sidebar-footer{flex:0 0 auto;margin-top:12px;padding:14px 4px 0;border-top:1px solid #ffffff24}.sidebar-footer form{margin:0}.sidebar-logout{display:flex;align-items:center;gap:11px;width:100%;min-height:42px;padding:10px 12px;border:1px solid #ffffff38;border-radius:8px;background:transparent;color:#fff;text-align