.sidebar{width:264px!important;z-index:1045}.sidebar-mobile-head,.mobile-menu{display:none}.nav-section{margin:15px 13px 3px;color:#9fc9bc;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.12em}.side-nav .nav-soon{position:relative;display:flex;align-items:center;gap:11px;min-height:44px;padding:11px 13px;border:0;border-radius:8px;background:transparent;color:#d6e8e2;text-align:left;font-size:14px}.side-nav .nav-soon:hover{background:#ffffff12;color:#fff}.nav-soon small{margin-left:auto;padding:3px 6px;border-radius:999px;background:var(--gold-pale);color:#805d16;font-size:9px;font-weight:800;text-transform:uppercase}.modal-content{color:var(--text);border:0;border-radius:12px}.modal-footer .btn{background:var(--green);color:#fff}.mobile-menu{align-items:center;gap:7px;padding:8px 11px;border:1px solid var(--border);border-radius:8px;background:#fff;color:var(--dark);font-weight:700}
@media(min-width:1024px){.sidebar.offcanvas-lg{position:fixed!important;inset:0 auto 0 0!important;height:100vh!important;background-color:var(--dark)!important;color:#fff!important;border-right:0!important;transform:none!important;visibility:visible!important}}
.nav-group{margin-top:8px}.nav-group-links{display:grid;gap:4px;padding:2px 0 5px 10px}.nav-group-links a,.nav-group-links .nav-soon{min-height:40px;padding-top:9px;padding-bottom:9px}.nav-group-links .nav-soon{width:100%}
