.metrics{gap:16px}.metric{padding:19px}.metric.success{border-top:3px solid var(--green)}.metric.warning{border-top:3px solid var(--gold)}.metric-label{margin:0 0 4px;color:#475569;font-size:11px;font-weight:800}.metric-value{font-size:29px}.metric-note{margin:5px 0 0;font-size:11px}.metric-icon{display:none}
