/* Shared interaction and status colors from the PNMG palette. */
.side-nav a.active{background:var(--green)}
.btn:hover,.btn:focus-visible{background:var(--green-hover);color:#fff}
.btn.secondary:hover{background:var(--bg);color:var(--text)}
.btn.danger{color:#fff;background:var(--danger-text);border-bottom:3px solid var(--danger)}
.btn.danger:hover{background:#851c28}
.btn.warning,.btn.warning:hover{background:var(--warning);color:var(--text)}
.status-to_renew,.status-suspended{background:var(--warning-pale);color:#824519;border:1px solid var(--warning)}
.alert.warning{background:var(--warning-pale);border-color:var(--warning);color:#824519}
.errors,.alert.danger{border-left:3px solid var(--danger);color:var(--danger-text)}
.status-active,.status-valid{color:var(--green)}
.pnmg-pagination{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;width:100%;font-size:13px}.pnmg-pagination p{margin:0;color:var(--muted)}.pnmg-pagination ul{display:flex;align-items:center;gap:5px;margin:0;padding:0;list-style:none}.pnmg-pagination a,.pnmg-pagination li>span{min-width:36px;height:36px;padding:0 10px;border:1px solid var(--border);border-radius:7px;background:#fff;display:grid;place-items:center;color:var(--text);text-decoration:none;font-weight:700}.pnmg-pagination a:hover,.pnmg-pagination a:focus-visible{border-color:var(--green);color:var(--green)}.pnmg-pagination .active>span{border-color:var(--green);background:var(--green);color:#fff}.pnmg-pagination .disabled>span{background:#f4f7f6;color:#94a3b8;cursor:not-allowed}@media(max-width:600px){.pnmg-pagination{align-items:flex-start;flex-direction:column}.pnmg-pagination ul{max-width:100%;overflow-x:auto;padding-bottom:3px}}

