.side-nav{padding-bottom:20px}.nav-group{margin-top:9px}.nav-group-title{margin:0;padding:10px 13px 6px;color:#9fc9bc;font:800 11px/1.2 "Maiandra GD", Calibri, "Segoe UI", Arial, sans-serif;text-transform:uppercase;letter-spacing:.1em}.nav-group-links{display:grid;gap:3px;padding:0 0 4px 10px}.nav-group-links a{min-height:38px;padding-top:8px;padding-bottom:8px}.topbar{position:relative;z-index:30}.account-menu{flex:0 0 auto}.account-trigger{display:flex;align-items:center;gap:10px;max-width:280px;padding:7px 9px;border:1px solid #d9e2df;border-radius:11px;background:#fff;color:var(--text);text-align:left;cursor:pointer;transition:border-color .15s ease,box-shadow .15s ease}.account-trigger:hover,.account-trigger[aria-expanded=true]{border-color:#9cc8ba;box-shadow:0 0 0 3px #e8f5f0}.account-avatar{width:36px;height:36px;flex:0 0 36px;display:grid;place-items:center;border-radius:10px;background:var(--dark);color:#fff;font-size:12px;font-weight:900;letter-spacing:.04em}.account-avatar.large{width:46px;height:46px;flex-basis:46px;border-radius:13px;background:var(--green);font-size:14px}.account-trigger-copy{min-width:0;display:block}.account-trigger-copy strong,.account-trigger-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account-trigger-copy strong{font-size:13px}.account-trigger-copy small{margin-top:2px;color:var(--muted);font-size:10px}.account-chevron{color:#64748b;font-size:14px}.account-dropdown{width:min(340px,calc(100vw - 24px));margin-top:8px!important;padding:0;border:1px solid #dce5e2;border-radius:14px;box-shadow:0 18px 42px #173f3426;overflow:hidden}.account-dropdown-head{display:flex;align-items:center;gap:12px;padding:18px;background:linear-gradient(135deg,#264653,#315f6f);color:#fff}.account-dropdown-head strong,.account-dropdown-head small{display:block}.account-dropdown-head strong{font:700 17px/1.2 Corbel, Calibri, "Segoe UI", Arial, sans-serif}.account-dropdown-head small{margin-top:4px;color:#d9e8e4;font-si