@media(max-width:760px){.topbar{gap:10px}.account-trigger{max-width:none;padding:5px;border:0}.account-trigger-copy,.account-chevron{display:none}.account-avatar{width:34px;height:34px;flex-basis:34px}.account-dropdown{position:fixed!important;top:58px!important;right:12px!important;left:auto!important;transform:none!important}.brand{margin-bottom:18px}}
.nav-icon{width:18px;height:18px;flex:0 0 18px;stroke-width:1.9}.account-chevron{width:16px;height:16px;flex:0 0 16px}.account-profile-link,.account-logout{display:flex;align-items:center;justify-content:center;gap:7px}.account-profile-link svg,.account-logout svg{width:16px;height:16px;stroke-width:2}.notification-symbol svg{width:16px;height:16px;stroke-width:2.2}.topbar{position:sticky;top:0;z-index:1030}.mobile-menu{width:42px;height:42px;flex:0 0 42px;align-items:center;justify-content:center;gap:0;padding:0}.mobile-menu svg{width:20px;height:20px;stroke-width:2}.pnmg-pagination svg{width:16px;height:16px;stroke-width:2}.lucide{display:inline-block;vertical-align:middle}
